namespace Pr7Editor {
public sealed class PlayerItem {public int Index,Id,NameIndex;public string Name;public override string ToString(){return Name+"  ["+Id+"]";}}
public sealed class Choice {public long Id;public string Name;public override string ToString(){return L.T(Name);}}
public sealed class AssetItem {public Asset Asset;public string Label,Prefix="";public override string ToString(){return (Prefix.Length>0?L.T(Prefix)+" ? ":"")+Label;}}
public sealed partial class Session {
 public static string DefaultRoot(){foreach(string p in new[]{AppDomain.CurrentDomain.BaseDirectory,Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,".."))})try{return Resolve(p);}catch(DirectoryNotFoundException){}throw new DirectoryNotFoundException("Selecciona la carpeta del port o GameData.");}
 public string Root;public List<Archive> Archives=new List<Archive>();public List<Asset> Assets=new List<Asset>();public GameDatabase Db;public Asset DbAsset,MetaAsset;public byte[] Meta;public bool DbDirty;public AppearanceRules Appearance;
 public List<PlayerItem> Players=new List<PlayerItem>();public Dictionary<Asset,byte[]> Pending=new Dictionary<Asset,byte[]>();
 public static string Resolve(string path){foreach(string p in new[]{path,Path.Combine(path,"game"),Path.Combine(path,"GameData"),Path.Combine(path,"analysis","private","game")})if(File.Exists(Path.Combine(p,"data0.big"))&&File.Exists(Path.Combine(p,"data0.bh")))return Path.GetFullPath(p);throw new DirectoryNotFoundException("Selecciona la carpeta del port o la que contiene data0.big y data0.bh.");}
 public Session(string path){Root=Resolve(path);for(int i=0;i<7;i++){string f=Path.Combine(Root,"data"+i+".big");if(File.Exists(f)){var a=new Archive(f);Archives.Add(a);Assets.AddRange(a.Entries);}}
  DbAsset=Assets.Single(a=>a.Name.Equals("data/db/fifa_ng_db.db",StringComparison.OrdinalIgnoreCase));MetaAsset=Assets.Single(a=>a.Name.Equals("data/db/fifa_ng_db-meta.xml",StringComparison.OrdinalIgnoreCase));Meta=MetaAsset.Archive.Read(MetaAsset);Db=new GameDatabase(DbAsset.Archive.Read(DbAsset),Meta);
  var names=Db.Rows("playernames");var ni=names.Select((r,i)=>new{Id=(int)GameDatabase.Number(r,"playerid"),Index=i}).ToDictionary(r=>r.Id,r=>r.Index);var rows=Db.Rows("players");Appearance=new AppearanceRules(Assets,rows);
  for(int i=0;i<rows.Count;i++){int id=(int)GameDatabase.Number(rows[i],"playerid"),index;if(!ni.TryGetValue(id,out index))continue;var n=names[index];string name=(Convert.ToString(n["firstname"])+" "+Convert.ToString(n["surname"])).Trim();string common=Convert.ToString(n["commonname"]);if(common.Length>0&&name.IndexOf(common,StringComparison.OrdinalIgnoreCase)<0)name+=" ("+common+")";Players.Add(new PlayerItem{Id=id,Index=i,NameIndex=index,Name=name});}
 }
 public byte[] Read(Asset a){byte[] b;return Pending.TryGetValue(a,out b)?b:a.Archive.Read(a);}
 public Dictionary<Asset,byte[]> Collect(){var changes=new Dictionary<Asset,byte[]>(Pending);if(DbDirty){byte[] b=Db.Serialize();var checkedDb=new GameDatabase(b,Meta);checkedDb.Rows("playernames");changes[DbAsset]=b;}return changes;}
}
public sealed partial class TexturePanel:UserControl {
 readonly EditorForm Owner;readonly string Kind;List<AssetItem> All=new List<AssetItem>();TextBox Filter=new TextBox();ListBox Files=new ListBox();ComboBox Surfaces=new EditorComboBox();ComboBox Category=new EditorComboBox();PictureBox Preview=new PictureBox();Label Info=new Label();Asset Current;byte[] BytesCurrent;List<Texture> Textures=new List<Texture>();bool Loading;
 public TexturePanel(EditorForm owner,string kind){Owner=owner;Kind=kind;Dock=DockStyle.Fill;var split=new SplitContainer{Dock=DockStyle.Fill,Width=1100,SplitterDistance=440};Controls.Add(split);
  var left=new Panel{Dock=DockStyle.Fill,Padding=new Padding(8)};split.Panel1.Controls.Add(left);Files.Dock=DockStyle.Fill;Filter.Dock=DockStyle.Top;var hint=new Label{Dock=DockStyle.Top,Height=28,Text="Buscar nombre, equipo, ID o archivo"};left.Controls.Add(Files);left.Controls.Add(Filter);left.Controls.Add(hint);if(Kind=="Caras"){Category.Dock=DockStyle.Top;Category.DropDownStyle=ComboBoxStyle.DropDownList;foreach(var c in new[]{new Choice{Id=0,Name="Todas las caras y pieles"},new Choice{Id=1,Name="Caras individuales"},new Choice{Id=2,Name="Piel corporal"},new Choice{Id=3,Name="Ojos y cabeza"},new Choice{Id=4,Name="Mapas corporales compartidos"}})Category.Items.Add(c);Category.SelectedIndex=0;left.Controls.Add(Category);Category.SelectedIndexChanged+=(s,e)=>{if(!Loading){Loading=true;Filter.Text="";Loading=false;RefreshList();}};}
  var right=new Panel{Dock=DockStyle.Fill,Padding=new Padding(8)};split.Panel2.Controls.Add(right);Preview.Dock=DockStyle.Fill;Preview.SizeMode=PictureBoxSizeMode.Zoom;Preview.BackColor=Color.FromArgb(43,47,56);Surfaces.Dock=DockStyle.Top;Surfaces.DropDownStyle=ComboBoxStyle.DropDownList;Info.Dock=DockStyle.Bottom;Info.Height=65;
  var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=80,AutoSize=false};foreach(string text in new[]{"Exportar PNG","Exportar DDS","Importar PNG","Importar DDS"}){var btn=new Button{Text=text,Width=145,Height=30};string action=text;btn.Click+=(s,e)=>Owner.Run(()=>Transfer(action));buttons.Controls.Add(btn);}
  var restore=new Button{Text="Restaurar este recurso",Width=190,Height=30};restore.Click+=(s,e)=>Owner.Run(()=>{if(Current==null)throw new InvalidOperationException("Selecciona un recurso.");Owner.PrepareResourceRestore(Current);LoadAsset();});buttons.Controls.Add(restore);

  right.Controls.Add(Preview);right.Controls.Add(Surfaces);right.Controls.Add(buttons);right.Controls.Add(Info);Filter.TextChanged+=(s,e)=>{if(!Loading)RefreshList();};Files.SelectedIndexChanged+=(s,e)=>{if(!Loading)Owner.Run(LoadAsset);};Surfaces.SelectedIndexChanged+=(s,e)=>{if(!Loading)Owner.Run(ShowTexture);};
 }
 public void Bind(Session session){All.Clear();var playerNames=session.Players.ToDictionary(p=>p.Id,p=>p.Name);var teams=session.Db.Rows("teams").GroupBy(r=>GameDatabase.Number(r,"assetid")).ToDictionary(g=>(int)g.Key,g=>Convert.ToString(g.First()["teamname"]));
  foreach(var a in session.Assets){string n=a.Name.ToLowerInvariant();if(!n.EndsWith(".rx2"))continue;bool match=TextureCatalog.Includes(Kind,n);if(!match)continue;
   string filename=Path.GetFileName(n);var m=Regex.Match(filename,@"^[a-z]+_(\d+)");string label=filename;int id;if(TextureCatalog.Prefix(n).Length==0&&m.Success&&Int32.TryParse(m.Groups[1].Value,out id)){string name;if((Kind=="Caras"?playerNames:teams).TryGetValue(id,out name)&&Kind!="Botines")label=name+" · "+filename;else label="ID "+id+" · "+filename;}All.Add(new AssetItem{Asset=a,Label=label,Prefix=TextureCatalog.Prefix(n)});
  }All=All.OrderBy(a=>a.Label).ToList();Filter.Text="";RefreshList();LoadAsset();
 }
 void RefreshList(){Loading=true;Files.BeginUpdate();Files.Items.Clear();string f=Filter.Text.Trim();foreach(var a in All)if((Kind!="Caras"||((Choice)Category.SelectedItem).Id==0||TextureCatalog.FaceCategory(a.Asset.Name)==((Choice)Category.SelectedItem).Id)&&EditorForm.Contains(a.ToString(),f))Files.Items.Add(a);Files.EndUpdate();Loading=false;if(Files.Items.Count>0)Files.SelectedIndex=0;else Clear();}
 void Clear(){Current=null;BytesCurrent=null;Textures.Clear();Loading=true;Surfaces.Items.Clear();Loading=false;var old=Preview.Image;Preview.Image=null;if(old!=null)old.Dispose();Info.Text=L.T("Sin texturas seleccionadas.");}
 void LoadAsset(){var item=Files.SelectedItem as AssetItem;if(item==null){Clear();return;}Clear();Current=item.Asset;BytesCurrent=(byte[])Owner.State.Read(Current).Clone();Textures=Texture.Parse(BytesCurrent);TextureCatalog.Describe(Current.Name,Textures);Loading=true;Surfaces.Items.Clear();Surfaces.Items.AddRange(Textures.Cast<object>().ToArray());Loading=false;
  if(Textures.Count==0){var old=Preview.Image;Preview.Image=null;if(old!=null)old.Dispose();Info.Text=Current.Name+"\r\n"+L.T("Sin superficies 2D compatibles; no se modificara.");return;}
  var preferred=Textures.Where(t=>t.Format==18).OrderByDescending(t=>t.Width*t.Height).FirstOrDefault()??Textures.OrderByDescending(t=>t.Width*t.Height).First();Surfaces.SelectedIndex=Textures.IndexOf(preferred);ShowTexture();
 }
 void ShowTexture(){var t=Surfaces.SelectedItem as Texture;var old=Preview.Image;Preview.Image=t==null?null:t.Preview();if(old!=null)old.Dispose();UpdateInfo();}
 void Transfer(string action){var t=Surfaces.SelectedItem as Texture;if(t==null||Current==null)throw new InvalidOperationException("Selecciona una textura compatible.");bool export=action.StartsWith("Exportar"),dds=action.EndsWith("DDS");string filename=Path.GetFileNameWithoutExtension(Current.Name)+".texture"+t.Section+(dds?".dds":".png");
  if(export){using(var d=new SaveFileDialog{Filter=dds?"DDS|*.dds":"PNG|*.png",FileName=filename,InitialDirectory=Owner.ExportDirectory})if(d.ShowDialog(Owner)==DialogResult.OK){if(dds)File.WriteAllBytes(d.FileName,t.Dds());else using(var b=t.Preview())b.Save(d.FileName,ImageFormat.Png);Owner.Note("Exportado: "+d.FileName);}}
  else using(var d=new OpenFileDialog{Filter=dds?"DDS|*.dds":"PNG|*.png"})if(d.ShowDialog(Owner)==DialogResult.OK){
   // Failed imports must never partially alter the preview or queued resource.
   byte[] copy=(byte[])BytesCurrent.Clone();var replacement=Texture.Parse(copy).Single(x=>x.Section==t.Section);if(dds)replacement.ImportDds(File.ReadAllBytes(d.FileName));else replacement.ImportPng(d.FileName);
   Owner.State.Pending[Current]=copy;BytesCurrent=copy;int section=t.Section;Textures=Texture.Parse(copy);TextureCatalog.Describe(Current.Name,Textures);Loading=true;Surfaces.Items.Clear();Surfaces.Items.AddRange(Textures.Cast<object>().ToArray());Loading=false;Surfaces.SelectedIndex=Textures.FindIndex(x=>x.Section==section);ShowTexture();Owner.Note("Reemplazo pendiente: "+Current.Name+". Pulsa Guardar cambios para aplicarlo.");
  }
 }
 public void FocusId(int id){if(Kind=="Caras")Category.SelectedIndex=1;Filter.Text=(Kind=="Caras"?"face_":Kind=="Botines"?"shoe_":"kit_")+id+"_";LoadAsset();}
}
