 public Session State;public string ExportDirectory;readonly string BackupRoot;bool Busy,Loading;TextBox RootPath=new TextBox(),Search=new TextBox();ComboBox League=new EditorComboBox(),Team=new EditorComboBox();PlayerListControl PlayerList=new PlayerListControl();DataGridView Fields=new DataGridView();Label Status=new Label(),PlayerTitle=new Label(),LeagueCaption=new Label(),TeamCaption=new Label();TabControl Tabs=new EditorTabs();TexturePanel Faces,Kits,Shoes;List<PlayerItem> VisiblePlayers=new List<PlayerItem>();Dictionary<long,HashSet<long>> TeamPlayers=new Dictionary<long,HashSet<long>>();HashSet<long> AllowedTeams;PlayerItem Selected;
 public EditorForm(){Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);Text="FIFA08 editor by pr7";Width=1240;Height=820;MinimumSize=new Size(1000,680);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",9);BackColor=Color.FromArgb(244,246,250);string editorData=AppDomain.CurrentDomain.BaseDirectory;if(!Path.GetFileName(editorData.TrimEnd(Path.DirectorySeparatorChar)).Equals("modding",StringComparison.OrdinalIgnoreCase))editorData=Path.Combine(editorData,Directory.Exists(Path.Combine(editorData,"bin"))?"mods/editor":"modding");BackupRoot=Path.Combine(editorData,"backups");ExportDirectory=Path.Combine(editorData,"exports");Directory.CreateDirectory(ExportDirectory);
