 }
 Button Button(string text,Action action){var b=new Button{Text=text,Width=145,Height=28};b.Click+=(s,e)=>Run(action);return b;}
 public static bool Contains(string text,string query){return CultureInfo.InvariantCulture.CompareInfo.IndexOf(text??"",query??"",CompareOptions.IgnoreCase|CompareOptions.IgnoreNonSpace)>=0;}
 public void Run(Action action){if(Busy)return;Busy=true;UseWaitCursor=true;try{action();}catch(Exception ex){MessageBox.Show(this,L.T(ex.Message),"FIFA08 editor by pr7",MessageBoxButtons.OK,MessageBoxIcon.Error);Note("No se completo la operacion: "+ex.Message);}finally{UseWaitCursor=false;Busy=false;}}
 public void Note(string s){statusSource=s;Status.Text=L.T(s);}
 bool HasPending{get{return State!=null&&(State.DbDirty||State.Pending.Count>0);}}
 void OpenFolder(){if(HasPending&&MessageBox.Show(this,"¿Descartar los cambios pendientes y abrir otra carpeta?",Text,MessageBoxButtons.YesNo)!=DialogResult.Yes)return;using(var d=new FolderBrowserDialog{Description=L.T("Selecciona la carpeta del port o GameData"),SelectedPath=State==null?AppDomain.CurrentDomain.BaseDirectory:State.Root})if(d.ShowDialog(this)==DialogResult.OK)LoadGame(d.SelectedPath);}
 public void LoadGame(string path){string resolved=Session.Resolve(path);OriginalBackupStore.RecoverPending(resolved,BackupRoot);State=new Session(resolved);sortedPlayers=State.Players.OrderBy(p=>p.Name).ToArray();Selected=null;Fields.Rows.Clear();AppearanceGrid.Rows.Clear();RootPath.Text=State.Root;Loading=true;TeamPlayers.Clear();foreach(var row in State.Db.Rows("teamplayerlinks")){long tid=GameDatabase.Number(row,"teamid"),pid=GameDatabase.Number(row,"playerid");HashSet<long> set;if(!TeamPlayers.TryGetValue(tid,out set))TeamPlayers[tid]=set=new HashSet<long>();set.Add(pid);}
  League.Items.Clear();League.Items.Add(new Choice{Id=-1,Name="Todas las ligas"});foreach(var l in State.Db.Rows("leagues").OrderBy(r=>Convert.ToString(r["leaguename"])))League.Items.Add(new Choice{Id=GameDatabase.Number(l,"leagueid"),Name=Convert.ToString(l["leaguename"])});League.SelectedIndex=0;Search.Text="";Loading=false;UpdateTeams();Faces.Bind(State);Kits.Bind(State);Shoes.Bind(State);Note("Base deportiva global cargada: "+State.Players.Count+" jugadores. Los textos de interfaz por idioma no se alteran.");}
 void BuildPlayers(TabPage page){BuildPlayerLayout(page);}
 void UpdateTeams(){if(State==null)return;Loading=true;var l=League.SelectedItem as Choice;LeagueCaption.Text=L.T("Liga: ")+(l==null?"":l.ToString());AllowedTeams=null;if(l!=null&&l.Id!=-1)AllowedTeams=new HashSet<long>(State.Db.Rows("leagueteamlinks").Where(r=>GameDatabase.Number(r,"leagueid")==l.Id).Select(r=>GameDatabase.Number(r,"teamid")));
  Team.Items.Clear();Team.Items.Add(new Choice{Id=-1,Name="Todos los equipos"});foreach(var t in State.Db.Rows("teams").OrderBy(r=>Convert.ToString(r["teamname"]))){long id=GameDatabase.Number(t,"teamid");if(AllowedTeams==null||AllowedTeams.Contains(id))Team.Items.Add(new Choice{Id=id,Name=Convert.ToString(t["teamname"])});}Team.SelectedIndex=0;Loading=false;FilterPlayers();}
 void FilterPlayers(){if(State==null)return;if(!Loading&&Selected!=null)ApplyPlayerCore();var t=Team.SelectedItem as Choice;TeamCaption.Text=L.T("Equipo: ")+(t==null?"":t.ToString());HashSet<long> ids=null;if(t!=null&&t.Id!=-1){TeamPlayers.TryGetValue(t.Id,out ids);if(ids==null)ids=new HashSet<long>();}else if(AllowedTeams!=null){ids=new HashSet<long>();foreach(long id in AllowedTeams){HashSet<long> set;if(TeamPlayers.TryGetValue(id,out set))ids.UnionWith(set);}}
  string query=Search.Text;var matches=ids==null&&query.Length==0?sortedPlayers:sortedPlayers.Where(p=>(ids==null||ids.Contains(p.Id))&&(Contains(p.Name,query)||p.Id.ToString().Contains(query))).ToArray();
  int previous=Selected==null?-1:Selected.Id;bool wasLoading=Loading;Loading=true;PlayerList.BeginUpdate();try{PlayerList.Items.Clear();PlayerList.Items.AddRange(matches);int selected=Array.FindIndex(matches,p=>p.Id==previous);if(matches.Length>0)PlayerList.SelectedIndex=selected>=0?selected:0;}finally{PlayerList.EndUpdate();Loading=wasLoading;}ShowPlayer();}
 static readonly Dictionary<string,string> Labels=new Dictionary<string,string>{{"overallrating","Media general"},{"shoetypecode","Botines: ID"},{"shoecolorcode1","Botines: color"},{"jerseystylecode","Camiseta: estilo (0/1)"},{"jerseysleevelengthcode","Camiseta: mangas (0/1)"},{"firstname","Nombre"},{"surname","Apellido"},{"commonname","Nombre habitual"},{"playerjerseyname","Nombre en camiseta"},{"acceleration","Aceleracion"},{"sprintspeed","Velocidad"},{"finishing","Definicion"},{"shortpassing","Pase corto"},{"longpassing","Pase largo"},{"dribbling","Regate"},{"ballcontrol","Control"},{"shotpower","Potencia de tiro"},{"stamina","Resistencia"}};
 void ShowPlayer(){ShowPlayerCore();}
 void ApplyPlayer(){ApplyPlayerCore();}
 void Save(){if(State==null)return;if(Selected!=null)ApplyPlayer();var changes=State.Collect();if(changes.Count==0){Note("No hay cambios preparados. Usa Preparar jugador o importa una textura.");return;}
  string summary=String.Join("\r\n",changes.Keys.Select(a=>Path.GetFileName(a.Archive.FileName)+": "+a.Name));if(MessageBox.Show(this,"Se aplicaran "+changes.Count+" recursos con respaldo automatico.\r\n\r\n"+summary+"\r\n\r\nLas plantillas guardadas pueden tener prioridad sobre los datos base. ¿Guardar?",Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
  Note("Guardando y verificando respaldos... puede tardar al copiar los BIG.");Status.Refresh();string backup=Storage.Save(State.Root,changes,BackupRoot);string root=State.Root;LoadGame(root);Note("Guardado completado. Respaldo: "+backup);MessageBox.Show(this,L.T("Cambios guardados.\r\n\r\nRespaldo: "+backup+"\r\n\r\nPrueba el juego con una plantilla nueva o restablecida para verificar los datos base."),Text);
