public static class Program {
 [STAThread]public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Length>0&&args[0]=="--self-test"){SelfTest.Run(args.Length>1?args[1]:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests","output"));return;}
  if(args.Length==4&&args[0]=="--compact-backups"){File.WriteAllText(args[3],OriginalBackupStore.Compact(Session.Resolve(args[1]),args[2]));return;}
  if(args.Length==2&&args[0]=="--individual-test"){string project=AppDomain.CurrentDomain.BaseDirectory;if(!Directory.Exists(Path.Combine(project,"analysis","modding-research")))project=Path.GetFullPath(Path.Combine(project,".."));Directory.CreateDirectory(args[1]);File.WriteAllLines(Path.Combine(args[1],"resultados.txt"),IndividualRestoreTests.Run(project,args[1]));return;}
  if(args.Length==3&&args[0]=="--audit-textures"){SelfTest.Audit(args[1],args[2]);return;}
  if((args.Length>=3&&args.Length<=5)&&args[0]=="--preview"){using(var f=new EditorForm()){if(args.Length>=4)f.SetDarkTheme(args[3]!="light");if(args.Length==5)f.SetEnglish(args[4]=="en",false);f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-30000,-30000);f.Show();Application.DoEvents();f.LoadGame(args[1]);Application.DoEvents();f.PreviewTo(args[2]);f.ValidatePlayerUi();f.ValidateThemeUi();f.ValidateLanguageUi(args[2]+".language-test.txt");f.ValidateCatalogUi();File.WriteAllText(args[2]+".ui-test.txt","PASS: Scholes shoe116/color0; rating93; filter commits previous player; new selection correct; light/dark and EN/ES preserve pending edits; shorts/socks atlas and ten skins present; no game writes.");f.State.DbDirty=false;f.State.Pending.Clear();f.Close();}return;}
  Application.Run(new EditorForm());}catch(Exception e){if(args.Length>0){Console.Error.WriteLine(e.ToString());File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"error-test.txt"),e.ToString());Environment.ExitCode=1;}else MessageBox.Show(e.Message,"FIFA08 editor by pr7",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
